const wfId = input.workflowId;
if (!wfId) return { error: 'No workflowId provided' };
const res = await fetch(apiUrl + '/workflows/' + wfId, {
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' }
});
if (!res.ok) {
  const err = await res.text();
  return { error: 'Failed to fetch workflow: ' + res.status + ' ' + err };
}
const data = await res.json();
const wf = data.data || data;
return {
  workflowId: String(wf._id),
  name: wf.name,
  description: wf.description,
  isActive: wf.isActive,
  steps: wf.steps,
  stepCount: (wf.steps || []).length,
  inputSchema: wf.inputSchema || null,
  samplePayload: wf.samplePayload || null,
  rootTaskTitleTemplate: wf.rootTaskTitleTemplate || null,
  color: wf.color || null,
  groupId: wf.groupId ? String(wf.groupId) : null
};

const modeOverride = (trigger && trigger.mode) || '';
if (modeOverride === 'question' || modeOverride === 'edit') {
  return { intent: modeOverride, complexity: modeOverride === 'edit' ? 'moderate' : 'simple', override: true };
}

const instruction = (trigger && trigger.instruction) || '';
const lower = instruction.toLowerCase().trim();

const questionPatterns = /^(what|why|how|when|where|who|which|is |are |does |do |can |could |would |should |tell me|explain|describe|summarize|list |show me)/;
const hasQuestionMark = lower.includes('?');
const editPatterns = /\b(change|update|add|remove|delete|edit|rewrite|fix|improve|replace|insert|append|move|rename|modify|restructure|refactor|reorder|connect|disconnect|configure|enable|disable)\b/;

let intent = 'question';
let complexity = 'simple';

if (questionPatterns.test(lower) || hasQuestionMark) {
  intent = 'question';
  complexity = 'simple';
} else if (editPatterns.test(lower)) {
  intent = 'edit';
  complexity = lower.length > 200 ? 'complex' : 'moderate';
} else {
  intent = lower.length > 100 ? 'edit' : 'question';
  complexity = intent === 'edit' ? 'moderate' : 'simple';
}

return { intent, complexity };

const out = (input && input.output) || {};
const result = (out.result && typeof out.result === 'object') ? out.result : {};
const answer = String(result.answer || out.summary || 'No answer was produced.');
const summary = String(result.summary || out.summary || answer.split('\n')[0].slice(0, 160));
const referencedSteps = Array.isArray(result.referencedSteps) ? result.referencedSteps : [];
const followUps = Array.isArray(result.suggestedFollowUps) ? result.suggestedFollowUps : [];
const targetWorkflowId = (trigger && trigger.workflowId) || '';
const instruction = (trigger && trigger.instruction) || '';

let groupId = null;
if (targetWorkflowId) {
  try {
    const wfRes = await fetch(apiUrl + '/workflows/' + targetWorkflowId, {
      headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' }
    });
    if (wfRes.ok) {
      const wfData = await wfRes.json();
      const wf = wfData.data || wfData;
      if (wf && wf.groupId) groupId = String(wf.groupId);
    }
  } catch (e) { /* ignore — fall back to API key default */ }
}

let content = answer.trim();
if (referencedSteps.length > 0) {
  content += '\n\n---\n\n**Referenced steps:** ' + referencedSteps.map(s => '`' + s + '`').join(', ');
}

const title = ('Answer: ' + (instruction || 'Workflow question')).slice(0, 200);

const body = {
  title,
  content,
  summary,
  type: 'output',
  status: 'approved',
  tags: ['ai-answer', 'workflow-assistant'],
  metadata: {
    autoGenerated: true,
    richAnswer: {
      answer: content,
      summary,
      referencedSteps,
      followUps,
      sourceContext: 'workflow',
      sourceTargetId: targetWorkflowId,
      sourceInstruction: instruction
    }
  }
};
if (groupId) body.groupId = groupId;

const createRes = await fetch(apiUrl + '/documents', {
  method: 'POST',
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
if (!createRes.ok) {
  const err = await createRes.text();
  return { error: 'Failed to create answer document: ' + createRes.status + ' ' + err, answer, summary, followUps };
}
const createData = await createRes.json();
const doc = createData.data || createData;

return {
  success: true,
  answer: content,
  summary,
  followUps,
  referencedSteps,
  documentId: String(doc._id),
  documentTitle: doc.title,
  documentOperations: [{
    success: true,
    action: 'create',
    documentId: String(doc._id),
    title: doc.title
  }],
  richAnswer: {
    answer: content,
    summary,
    referencedSteps,
    followUps,
    sourceContext: 'workflow',
    sourceTargetId: targetWorkflowId,
    sourceInstruction: instruction,
    documentId: String(doc._id)
  }
};

const wfId = (trigger && trigger.workflowId) || (input && input.workflowId);
if (!wfId) return { error: 'No workflowId to save' };

const output = input.output || input;
const result = (output.result && typeof output.result === 'object') ? output.result : output;
const updated = result.updatedWorkflow || output.updatedWorkflow || null;
if (!updated) return { error: 'No updatedWorkflow found in agent output', availableKeys: Object.keys(output) };

const patchBody = {};
if (updated.name) patchBody.name = updated.name;
if (updated.description) patchBody.description = updated.description;
if (updated.steps) patchBody.steps = updated.steps;
if (updated.inputSchema) patchBody.inputSchema = updated.inputSchema;
if (updated.samplePayload) patchBody.samplePayload = updated.samplePayload;
if (updated.rootTaskTitleTemplate) patchBody.rootTaskTitleTemplate = updated.rootTaskTitleTemplate;

const res = await fetch(apiUrl + '/workflows/' + wfId, {
  method: 'PATCH',
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
  body: JSON.stringify(patchBody)
});

if (!res.ok) {
  const err = await res.text();
  return { error: 'Failed to save workflow: ' + res.status + ' ' + err };
}

await res.json();
return {
  success: true,
  workflowId: wfId,
  editSummary: result.editSummary || 'Workflow updated',
  editDetails: result.editDetails || '',
  stepsAdded: Array.isArray(result.stepsAdded) ? result.stepsAdded : [],
  stepsModified: Array.isArray(result.stepsModified) ? result.stepsModified : [],
  stepsRemoved: Array.isArray(result.stepsRemoved) ? result.stepsRemoved : [],
  suggestedFollowUps: Array.isArray(result.suggestedFollowUps) ? result.suggestedFollowUps : []
};

const out = (input && input.output) || {};
const editSummary = String(out.editSummary || 'Workflow updated');
const editDetails = String(out.editDetails || '');
const stepsAdded = Array.isArray(out.stepsAdded) ? out.stepsAdded : [];
const stepsModified = Array.isArray(out.stepsModified) ? out.stepsModified : [];
const stepsRemoved = Array.isArray(out.stepsRemoved) ? out.stepsRemoved : [];
const followUps = Array.isArray(out.suggestedFollowUps) ? out.suggestedFollowUps : [];
const targetWorkflowId = (trigger && trigger.workflowId) || out.workflowId || '';
const instruction = (trigger && trigger.instruction) || '';

let groupId = null;
if (targetWorkflowId) {
  try {
    const wfRes = await fetch(apiUrl + '/workflows/' + targetWorkflowId, {
      headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' }
    });
    if (wfRes.ok) {
      const wfData = await wfRes.json();
      const wf = wfData.data || wfData;
      if (wf && wf.groupId) groupId = String(wf.groupId);
    }
  } catch (e) { /* ignore */ }
}

let content = '## ' + editSummary + '\n\n';
if (editDetails) content += editDetails + '\n\n';

const diffLines = [];
if (stepsAdded.length > 0) diffLines.push('**Added:** ' + stepsAdded.map(s => '`' + s + '`').join(', '));
if (stepsModified.length > 0) diffLines.push('**Modified:** ' + stepsModified.map(s => '`' + s + '`').join(', '));
if (stepsRemoved.length > 0) diffLines.push('**Removed:** ' + stepsRemoved.map(s => '`' + s + '`').join(', '));
if (diffLines.length > 0) content += '### Changes\n\n' + diffLines.join('\n\n') + '\n';

const title = ('Edit: ' + (instruction || 'Workflow update')).slice(0, 200);

const body = {
  title,
  content,
  summary: editSummary,
  type: 'output',
  status: 'approved',
  tags: ['ai-edit', 'workflow-assistant'],
  metadata: {
    autoGenerated: true,
    richAnswer: {
      answer: content,
      summary: editSummary,
      followUps,
      sourceContext: 'workflow',
      sourceTargetId: targetWorkflowId,
      sourceInstruction: instruction,
      stepsAdded,
      stepsModified,
      stepsRemoved
    }
  }
};
if (groupId) body.groupId = groupId;

const createRes = await fetch(apiUrl + '/documents', {
  method: 'POST',
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
if (!createRes.ok) {
  const err = await createRes.text();
  return { error: 'Failed to create edit summary document: ' + createRes.status + ' ' + err, editSummary, followUps };
}
const createData = await createRes.json();
const doc = createData.data || createData;

return {
  success: true,
  workflowId: targetWorkflowId,
  editSummary,
  followUps,
  documentId: String(doc._id),
  documentTitle: doc.title,
  documentOperations: [{
    success: true,
    action: 'create',
    documentId: String(doc._id),
    title: doc.title
  }],
  richAnswer: {
    answer: content,
    summary: editSummary,
    followUps,
    sourceContext: 'workflow',
    sourceTargetId: targetWorkflowId,
    sourceInstruction: instruction,
    documentId: String(doc._id)
  }
};
